// Package domain contains shared IAM domain primitives.
package domain

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
)

// ID is the common representation of an entity identifier. Values are UUID
// version 4 strings, generated with crypto/rand.
type ID string

type UserID ID
type OrganizationID ID
type SessionID ID
type InviteID ID
type RoleID ID
type APIKeyID ID
type TokenFamilyID ID

// NewID returns a new random UUID version 4 identifier.
func NewID() (ID, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", fmt.Errorf("generate id: %w", err)
	}
	value[6] = (value[6] & 0x0f) | 0x40
	value[8] = (value[8] & 0x3f) | 0x80
	encoded := make([]byte, 36)
	hex.Encode(encoded[0:8], value[0:4])
	hex.Encode(encoded[9:13], value[4:6])
	hex.Encode(encoded[14:18], value[6:8])
	hex.Encode(encoded[19:23], value[8:10])
	hex.Encode(encoded[24:36], value[10:16])
	encoded[8], encoded[13], encoded[18], encoded[23] = '-', '-', '-', '-'
	return ID(encoded), nil
}

func newTypedID[T ~string](newValue func() (ID, error)) (T, error) {
	id, err := newValue()
	return T(id), err
}

func NewUserID() (UserID, error) { return newTypedID[UserID](NewID) }

func NewOrganizationID() (OrganizationID, error) { return newTypedID[OrganizationID](NewID) }

func NewSessionID() (SessionID, error) { return newTypedID[SessionID](NewID) }

func NewInviteID() (InviteID, error) { return newTypedID[InviteID](NewID) }

func NewRoleID() (RoleID, error) { return newTypedID[RoleID](NewID) }

func NewAPIKeyID() (APIKeyID, error) { return newTypedID[APIKeyID](NewID) }

func NewTokenFamilyID() (TokenFamilyID, error) { return newTypedID[TokenFamilyID](NewID) }

// ParseID validates the textual UUID representation before converting it to ID.
func ParseID(value string) (ID, error) {
	if len(value) != 36 || value[8] != '-' || value[13] != '-' || value[18] != '-' || value[23] != '-' {
		return "", errors.New("invalid id")
	}
	var raw [16]byte
	if _, err := hex.Decode(raw[:4], []byte(value[0:8])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[4:6], []byte(value[9:13])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[6:8], []byte(value[14:18])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[8:10], []byte(value[19:23])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[10:16], []byte(value[24:36])); err != nil {
		return "", errors.New("invalid id")
	}
	return ID(value), nil
}
package domain

import "errors"

var (
	ErrNotFound     = errors.New("not found")
	ErrConflict     = errors.New("conflict")
	ErrInvalid      = errors.New("invalid")
	ErrUnauthorized = errors.New("unauthorized")
)

// Error preserves a stable domain error category while allowing callers to
// attach a safe, human-readable message and an underlying cause.
type Error struct {
	Kind    error
	Message string
	Cause   error
}

func (e *Error) Error() string {
	if e.Message != "" {
		return e.Message
	}
	return e.Kind.Error()
}

func (e *Error) Unwrap() error { return e.Cause }

func (e *Error) Is(target error) bool { return target == e.Kind }

func NewNotFound(message string) error     { return newError(ErrNotFound, message) }
func NewConflict(message string) error     { return newError(ErrConflict, message) }
func NewInvalid(message string) error      { return newError(ErrInvalid, message) }
func NewUnauthorized(message string) error { return newError(ErrUnauthorized, message) }

func Wrap(kind, message string, cause error) error {
	category := ErrInvalid
	switch kind {
	case "not_found":
		category = ErrNotFound
	case "conflict":
		category = ErrConflict
	case "unauthorized":
		category = ErrUnauthorized
	}
	return &Error{Kind: category, Message: message, Cause: cause}
}

func newError(kind error, message string) error { return &Error{Kind: kind, Message: message} }

// IsKind reports whether err belongs to the requested domain category.
func IsKind(err, kind error) bool { return errors.Is(err, kind) }
// Package repository contains concurrency-safe in-memory persistence.
package repository

import (
	"sync"

	"benchmark.local/iam/internal/domain"
)

// UserRepository stores users and maintains a unique, normalized email index.
// Both maps are protected by mu; callers never receive a reference to the
// repository's stored PasswordMaterial byte slices.
type UserRepository struct {
	mu      sync.RWMutex
	users   map[domain.UserID]domain.User
	byEmail map[string]domain.UserID
}

// NewUserRepository creates an empty in-memory user repository.
func NewUserRepository() *UserRepository {
	return &UserRepository{
		users:   make(map[domain.UserID]domain.User),
		byEmail: make(map[string]domain.UserID),
	}
}

// NormalizeEmail returns the key used by the repository's email index.
func NormalizeEmail(email string) string {
	return domain.NormalizeEmail(email)
}

// Create stores a new user. The user's ID must be unique and its normalized
// email must not already belong to another user.
func (r *UserRepository) Create(user domain.User) error {
	normalizedEmail, err := domain.ValidateEmail(user.Email)
	if err != nil {
		return err
	}
	user.Email = normalizedEmail
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.users[user.ID]; exists {
		return domain.NewConflict("user already exists")
	}
	if _, exists := r.byEmail[user.Email]; exists {
		return domain.NewConflict("email already exists")
	}
	r.users[user.ID] = cloneUser(user)
	r.byEmail[user.Email] = user.ID
	return nil
}

// GetByID returns a detached copy of the user with the requested ID.
func (r *UserRepository) GetByID(id domain.UserID) (domain.User, error) {
	r.mu.RLock()
	user, exists := r.users[id]
	r.mu.RUnlock()
	if !exists {
		return domain.User{}, domain.NewNotFound("user not found")
	}
	return cloneUser(user), nil
}

// GetByEmail returns a detached copy of the user for an email address.
func (r *UserRepository) GetByEmail(email string) (domain.User, error) {
	r.mu.RLock()
	id, exists := r.byEmail[NormalizeEmail(email)]
	if exists {
		user := r.users[id]
		r.mu.RUnlock()
		return cloneUser(user), nil
	}
	r.mu.RUnlock()
	return domain.User{}, domain.NewNotFound("user not found")
}

// Update replaces an existing user while preserving email uniqueness.
func (r *UserRepository) Update(user domain.User) error {
	normalizedEmail, err := domain.ValidateEmail(user.Email)
	if err != nil {
		return err
	}
	user.Email = normalizedEmail
	r.mu.Lock()
	defer r.mu.Unlock()
	old, exists := r.users[user.ID]
	if !exists {
		return domain.NewNotFound("user not found")
	}
	if otherID, used := r.byEmail[user.Email]; used && otherID != user.ID {
		return domain.NewConflict("email already exists")
	}
	oldEmail := NormalizeEmail(old.Email)
	if oldEmail != user.Email {
		delete(r.byEmail, oldEmail)
		r.byEmail[user.Email] = user.ID
	}
	r.users[user.ID] = cloneUser(user)
	return nil
}

// Delete removes a user from both the primary store and email index.
func (r *UserRepository) Delete(id domain.UserID) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	user, exists := r.users[id]
	if !exists {
		return domain.NewNotFound("user not found")
	}
	delete(r.users, id)
	delete(r.byEmail, NormalizeEmail(user.Email))
	return nil
}

// List returns detached copies of all users. The order is unspecified.
func (r *UserRepository) List() []domain.User {
	r.mu.RLock()
	users := make([]domain.User, 0, len(r.users))
	for _, user := range r.users {
		users = append(users, cloneUser(user))
	}
	r.mu.RUnlock()
	return users
}

func cloneUser(user domain.User) domain.User {
	user.PasswordMaterial.Salt = append([]byte(nil), user.PasswordMaterial.Salt...)
	user.PasswordMaterial.Hash = append([]byte(nil), user.PasswordMaterial.Hash...)
	return user
}
